import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第六十一卦 中孚 风泽中孚 巽上兑下","description":"周易 - 第六十一卦 中孚 风泽中孚 巽上兑下","frontmatter":{"title":"第六十一卦 中孚 风泽中孚 巽上兑下","description":"周易 - 第六十一卦 中孚 风泽中孚 巽上兑下"},"headers":[],"relativePath":"zh/classics/zhouyi/062.md","filePath":"zh/classics/zhouyi/062.md"}'),l={name:"zh/classics/zhouyi/062.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="中孚" tabindex="-1">中孚 <a class="header-anchor" href="#中孚" aria-label="Permalink to “中孚”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>豚鱼吉，利涉大川，利贞。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>中孚，柔在内而刚得中。说而巽，孚，乃化邦也。豚鱼吉，信及豚鱼也。利涉大川，乘木舟虚也。中孚以利贞，乃应乎天也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽上有风，中孚；君子以议狱缓死。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>虞吉，有他不燕。象曰：初九虞吉， 志未变也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>鸣鹤在阴，其子和之，我有好爵，吾与尔靡之。象曰：其子和之，中心愿也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>得敌，或鼓或罢，或泣或歌。象曰：可鼓或罢，位不当也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>月几望，马匹亡，无咎。象曰：马匹亡，绝类上也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>有孚挛如，无咎。象曰：有孚挛如，位正当也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>翰音登于天，贞凶。象曰：翰音登于天，何可长也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
